html:
{% set logo = doc.company_logo or '/assets/wafd_one/images/wafd-almadinah-official.png' %}
<style>
@page { size:A4 portrait; margin:9mm 14mm 10mm; }
html,body,.print-format{margin:0!important;padding:0!important;background:#fff!important;}
.sheet{direction:rtl;font-family:Tahoma,Arial,sans-serif;color:#111;font-size:10.4px;line-height:1.58;box-sizing:border-box;height:275mm;position:relative;overflow:hidden;padding:0 1mm;page-break-after:avoid!important;page-break-inside:avoid!important;}
.head{display:table;width:100%;table-layout:fixed;border-bottom:1px solid #b88a2a;padding-bottom:3mm;margin-bottom:3.5mm}.head-left,.head-center,.head-right{display:table-cell;vertical-align:middle}.head-left{width:34%;text-align:left;font-size:8.8px;line-height:1.65;color:#555}.head-center{width:48%;text-align:center}.head-center b{font-size:15px}.head-center span{font-size:8.8px;color:#666}.head-right{width:18%;text-align:right}.logo{width:24mm;height:25mm;object-fit:contain}
h1{text-align:center;font-size:16px;text-decoration:underline;margin:1.5mm 0 3mm}p{margin:1.1mm 0;text-align:justify}.details{width:100%;border-collapse:collapse;margin:2.5mm 0;font-size:9.7px}.details td{border:1px solid #bbb;padding:1.8mm 2.2mm;vertical-align:top}.terms{border:1px solid #ccc;padding:2.2mm;margin-top:2.5mm}.terms ol{margin:1mm 5mm 0 0;padding:0}.terms li{margin:.35mm 0}
.approval{position:absolute;right:8mm;bottom:20mm;width:78mm;height:43mm;text-align:center;page-break-inside:avoid}.company-sign-title{font-weight:700;font-size:11px}.manager-title{font-weight:700;font-size:11px;margin-top:1mm}.name-wrap{position:relative;height:17mm;margin-top:1mm}.manager-name{position:absolute;left:0;right:0;bottom:1mm;font-weight:700;font-size:11px;z-index:2}.signature-img{position:absolute;left:50%;top:-3mm;transform:translateX(-50%);width:55mm;height:22mm;object-fit:contain;z-index:4}.stamp-img{position:absolute;left:50%;top:7mm;transform:translateX(-50%);width:58mm;height:34mm;object-fit:contain;z-index:3}.placeholder{display:inline-block;border-bottom:1px solid #777;width:42mm;height:9mm}
.footer{position:absolute;right:0;left:0;bottom:0;border-top:1px solid #b88a2a;padding-top:2.2mm;text-align:center;color:#666;font-size:8.6px}
</style>
<div class="sheet">
<div class="head"><div class="head-left"><div>{{ doc.company_address or 'حي الملك فهد، المدينة المنورة' }}</div><div dir="ltr">{{ doc.company_phone or '0500336989' }}</div><div dir="ltr">{{ doc.company_email or 'wafd.almadinah@gmail.com' }}</div></div><div class="head-center"><b>{{ doc.company_name or 'شركة وفد المدينة لخدمات الإعاشة' }}</b><br><span>WAFD AL-MADINAH CATERING SERVICES</span></div><div class="head-right"><img class="logo" src="{{ logo }}"></div></div>
<h1>تعهد والتزام إعاشة</h1>
<p>نحن <b>{{ doc.company_name or 'شركة وفد المدينة لخدمات الإعاشة' }}</b>، سجل تجاري رقم <b>{{ doc.company_cr or '7051832694' }}</b>، نتعهد بتقديم خدمات الإعاشة للمستفيدين في الفندق الموضح أدناه، وفق البيانات المعتمدة والاشتراطات الصحية والتنظيمية، مع ضمان جودة وسلامة الوجبات أثناء التجهيز والنقل والتسليم.</p>
<table class="details"><tr><td><b>رقم التعهد</b><br>{{ doc.name or '' }}</td><td><b>التاريخ</b><br>{{ doc.get_formatted('undertaking_date') if doc.undertaking_date else '' }}</td></tr><tr><td><b>الفندق</b><br>{{ doc.hotel or '' }}</td><td><b>البعثة أو العميل</b><br>{{ doc.mission or doc.second_party_name or '' }}</td></tr><tr><td><b>عدد المستفيدين</b><br>{{ doc.beneficiary_count or 0 }}</td><td><b>الجنسية</b><br>{{ doc.nationality or '' }}</td></tr><tr><td><b>مدة الخدمة</b><br>{{ doc.get_formatted('start_date') if doc.start_date else '' }} — {{ doc.get_formatted('end_date') if doc.end_date else '' }}</td><td><b>موقع التوريد</b><br>{{ doc.supply_location or doc.hotel or '' }}</td></tr><tr><td colspan="2"><b>الوجبات</b><br>{{ doc.meal_types or '' }}</td></tr></table>
<div class="terms"><b>الشروط والملاحظات:</b><ol><li>تقديم الوجبات المتفق عليها وفق العدد ونوع الوجبة والفترة الموضحة في التعهد.</li><li>الالتزام بمواعيد تجهيز ونقل وتسليم الوجبات دون تأخير.</li><li>الالتزام باشتراطات سلامة الغذاء والنظافة والتعبئة والنقل والحفظ الحراري.</li><li>تسليم الوجبات في موقع التوريد المحدد وبالكميات المعتمدة.</li><li>تزويد الفندق بالمستندات النظامية المطلوبة عند الطلب.</li><li>للفندق التحقق من الكميات والحالة الظاهرية عند الاستلام وإثبات أي ملاحظة فوراً.</li><li>لا يُعتد بأي تعديل في العدد أو المواعيد إلا بعد اعتماده من الشركة.</li></ol>{% if doc.additional_terms or doc.service_notes %}<div><b>بنود إضافية:</b> {{ doc.additional_terms or doc.service_notes }}</div>{% endif %}</div>
<div class="approval"><div class="company-sign-title">شركة وفد المدينة لخدمات الإعاشة</div><div class="manager-title">{{ doc.signatory_title or 'المدير العام' }}</div><div class="name-wrap">{% if doc.include_stamp and doc.company_stamp %}<img class="stamp-img" src="{{ doc.company_stamp }}">{% endif %}<div class="manager-name">{{ doc.authorized_signatory or doc.company_representative or 'نزار بن مذير بن ظفر' }}</div>{% if doc.include_signature and doc.signature_image %}<img class="signature-img" src="{{ doc.signature_image }}">{% else %}<span class="placeholder"></span>{% endif %}</div></div>
<div class="footer">{{ doc.company_name or 'شركة وفد المدينة لخدمات الإعاشة' }} — {{ doc.company_address or 'حي الملك فهد، المدينة المنورة' }} &nbsp; | &nbsp; <span dir="ltr">{{ doc.company_phone or '0500336989' }} &nbsp; | &nbsp; {{ doc.company_email or 'wafd.almadinah@gmail.com' }}</span></div>
</div>
